const upsertPolicy = `-- name: UpsertPolicy :one
INSERT INTO policies (project_id, spec, privy_policy_id, version, pushed_at)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (project_id) DO UPDATE
SET spec = EXCLUDED.spec,
    privy_policy_id = COALESCE(EXCLUDED.privy_policy_id, policies.privy_policy_id),
    version = policies.version + 1,
    pushed_at = COALESCE(EXCLUDED.pushed_at, policies.pushed_at),
    updated_at = now()
RETURNING id, project_id, spec, privy_policy_id, version, pushed_at, updated_at
`

type UpsertPolicyParams struct {
	ProjectID     pgtype.UUID        `json:"project_id"`
	Spec          []byte             `json:"spec"`
	PrivyPolicyID pgtype.Text        `json:"privy_policy_id"`
	Version       int32              `json:"version"`
	PushedAt      pgtype.Timestamptz `json:"pushed_at"`
}

func (q *Queries) UpsertPolicy(ctx context.Context, arg UpsertPolicyParams) (Policies, error) {
	row := q.db.QueryRow(ctx, upsertPolicy,
		arg.ProjectID,
		arg.Spec,
		arg.PrivyPolicyID,
		arg.Version,
		arg.PushedAt,
	)
	var i Policies
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Spec,
		&i.PrivyPolicyID,
		&i.Version,
		&i.PushedAt,
		&i.UpdatedAt,
	)
	return i, err
}

